      // Call the query and get the async generator in the result
      const result = await trpc.chatStream.query({ message });
      const generator = result as AsyncIterable<string>;

      for await (const chunk of generator) {
        setChunks((prev) => [...prev, chunk]);
      }
      setIsComplete(true);
