  const [chunks, setChunks] = useState<string[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const query = trpc.chatStream.useQuery(
    { message },
    {
      enabled: false, // we trigger manually
    },
  );

  const startStreaming = useCallback(async () => {
    if (isStreaming) return;

    setIsStreaming(true);
    setIsComplete(false);
    setError(null);
    setChunks([]);

    try {
      // Call the query and get the async generator in the result
      const result = await trpc.chatStream.query({ message });
      const generator = result as AsyncIterable<string>;

      for await (const chunk of generator) {
        setChunks((prev) => [...prev, chunk]);
      }
      setIsComplete(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setIsStreaming(false);
    }
  }, [message, isStreaming]);

  const handleSend = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      setMessage(inputValue);
      // Reset and trigger
      setChunks([]);
      setIsComplete(false);
      setError(null);
    },
    [inputValue],
  );

  // When message changes, start streaming
  const prevMessage = useRef(message);
  useEffect(() => {
    if (prevMessage.current !== message || !isStreaming) {
      prevMessage.current = message;
      startStreaming();
    }
  }, [message]);

  return (
