"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { trpc } from "@/trpc/provider";

export default function Home() {
  const [message, setMessage] = useState("Tell me about tRPC streaming");
  const [inputValue, setInputValue] = useState("Tell me about tRPC streaming");
  const [chunks, setChunks] = useState<string[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  const query = trpc.chatStream.useQuery(
    { message },
    {
      enabled: false, // we trigger manually
    },
  );

  const startStreaming = useCallback(async () => {
    if (isStreaming) return;

    setIsStreaming(true);
    setIsComplete(false);
    setError(null);
    setChunks([]);

    try {
      // Call the query and get the async generator in the result
      const result = await trpc.chatStream.query({ message });
      const generator = result as AsyncIterable<string>;

      for await (const chunk of generator) {
        setChunks((prev) => [...prev, chunk]);
      }
      setIsComplete(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "An error occurred");
    } finally {
      setIsStreaming(false);
    }
  }, [message, isStreaming]);

  const handleSend = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      setMessage(inputValue);
      // Reset and trigger
      setChunks([]);
      setIsComplete(false);
      setError(null);
    },
    [inputValue],
  );

  // When message changes, start streaming
  const prevMessage = useRef(message);
  useEffect(() => {
    if (prevMessage.current !== message || !isStreaming) {
      prevMessage.current = message;
      startStreaming();
    }
  }, [message]);

  return (
    <div className="flex flex-col flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-black p-4">
      <main className="flex flex-col w-full max-w-3xl gap-6 py-8 px-4 bg-white dark:bg-black rounded-lg">
        <div className="text-center">
          <h1 className="text-2xl font-bold text-black dark:text-zinc-50">
            tRPC v11 Async Generator Streaming
          </h1>
          <p className="text-sm text-zinc-600 dark:text-zinc-400 mt-1">
            Streaming LLM-style responses over{" "}
            <code className="bg-zinc-100 dark:bg-zinc-800 px-1 rounded text-xs">
              httpBatchStreamLink
            </code>
          </p>
        </div>

        <form onSubmit={handleSend} className="flex gap-2">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            className="flex-1 px-4 py-2 border border-zinc-300 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-900 text-black dark:text-zinc-50 text-sm"
            placeholder="Type your message..."
          />
          <button
            type="submit"
            disabled={isStreaming}
            className="px-6 py-2 bg-zinc-900 dark:bg-zinc-50 text-white dark:text-black rounded-lg text-sm font-medium hover:opacity-80 disabled:opacity-50 transition-opacity"
          >
            {isStreaming ? "Streaming..." : "Send"}
          </button>
        </form>

        <div className="border border-zinc-200 dark:border-zinc-800 rounded-lg p-4 min-h-[300px] max-h-[500px] overflow-y-auto bg-zinc-50 dark:bg-zinc-900">
          {error ? (
            <div className="text-red-500 text-sm">{error}</div>
          ) : chunks.length === 0 && !isStreaming ? (
            <div className="text-zinc-400 dark:text-zinc-500 text-sm italic">
              Send a message to see the streamed response...
            </div>
          ) : (
            <div className="font-mono text-sm text-black dark:text-zinc-200 whitespace-pre-wrap">
              {chunks.map((chunk, i) => (
                <span
                  key={i}
                  className="animate-fadeIn"
                  style={{ animationDelay: "0ms" }}
                >
                  {chunk}
                </span>
              ))}
              {isStreaming && (
                <span className="inline-block w-2 h-4 bg-zinc-900 dark:bg-zinc-50 animate-pulse ml-0.5" />
              )}
            </div>
          )}
        </div>

        {isComplete && (
          <div className="text-center text-green-600 dark:text-green-400 text-sm">
            ✓ Streaming complete — {chunks.length} chunks received
          </div>
        )}

        <div className="text-xs text-zinc-400 dark:text-zinc-500 text-center">
          Powered by tRPC v11 • AsyncGenerator • httpBatchStreamLink • JSONL
        </div>
      </main>
    </div>
  );
}

