import {
  createTRPCClient,
  httpBatchStreamLink,
  type TRPCClientError,
} from "@trpc/client";
import superjson from "superjson";
import type { AppRouter } from "@/server/router";

function getBaseUrl() {
  if (typeof window !== "undefined") return "";
  return `http://localhost:${process.env.PORT ?? 3000}`;
}

const trpcClient = createTRPCClient<AppRouter>({
  links: [
    httpBatchStreamLink({
      url: `${getBaseUrl()}/api/trpc`,
      transformer: superjson,
    }),
  ],
});

export default function Home() {
  const [inputValue, setInputValue] = useState("Tell me about tRPC streaming");
  const [chunks, setChunks] = useState<string[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const triggeredRef = useRef(false);

  const startStream = useCallback(async (message: string) => {
    setIsStreaming(true);
    setIsComplete(false);
    setError(null);
    setChunks([]);

    try {
      const generator = await trpcClient.chatStream.query({ message });

      for await (const chunk of generator) {
        setChunks((prev) => [...prev, chunk]);
      }

      setIsComplete(true);
    } catch (err: unknown) {
      const tRPcError = err as TRPCClientError<unknown>;
      setError(tRPcError?.message ?? "An error occurred during streaming");
    } finally {
      setIsStreaming(false);
    }
  }, []);

  const handleSend = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault();
      triggeredRef.current = true;
      startStream(inputValue);
    },
    [inputValue, startStream],
  );

  return (
    <div className="flex flex-col flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-black p-4">
      <main className="flex flex-col w-full max-w-3xl gap-6 py-8 px-4 bg-white dark:bg-black rounded-lg">
        <div className="text-center">
          <h1 className="text-2xl font-bold text-black dark:text-zinc-50">
            tRPC v11 Async Generator Streaming
          </h1>
          <p className="text-sm text-zinc-600 dark:text-zinc-400 mt-1">
            Streaming LLM-style responses over{" "}
            <code className="bg-zinc-100 dark:bg-zinc-800 px-1 rounded text-xs">
              httpBatchStreamLink
            </code>
          </p>
        </div>

        <form onSubmit={handleSend} className="flex gap-2">
          <input
            type="text"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            className="flex-1 px-4 py-2 border border-zinc-300 dark:border-zinc-700 rounded-lg bg-white dark:bg-zinc-900 text-black dark:text-zinc-50 text-sm"
            placeholder="Type your message..."
          />
          <button
            type="submit"
            disabled={isStreaming}
            className="px-6 py-2 bg-zinc-900 dark:bg-zinc-50 text-white dark:text-black rounded

